/* update: blend two keyframes of a path and write the result to a position */
void interpolate_moby_and_linked_moby_positions_on_path(char *moby) {
    int *p = ((int *)((Moby *)moby)->pvars);
    int *t = eudora_paths[p[2]];
    char *base = eudora_mobys;
    int o0 = p[0] * 256;
    float *src = *(float **)(base + o0 + 0x78);
    char *dst = base + p[1] * 256;
    float a[4];
    float b[4];
    float f, g;
    int idx;
    int n = 1;
    float one = 1.0f;

    f = IntToFloat(t[0] - 1);
    g = (one - src[0]) * f;
    f = fast_fmod(g, one);
    idx = truncate_float_to_s32_r(g);
    if (f == 0.0f) n = 0;
    n += idx;
    FastVecScale(a, (char *)t + (idx * 16 + 0x10), one - f);
    FastVecScale(b, (char *)t + (n * 16 + 0x10), f);
    FastVecAdd(moby + 0x10, a, b);
    qcopy(dst + 0x10, moby + 0x10);
}
